CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
INSERT INTO public.user_roles(user_id,role) SELECT id,role FROM public.profiles;
CREATE OR REPLACE FUNCTION public.get_user_role(_user_id uuid) RETURNS public.app_role LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT role FROM public.user_roles WHERE user_id=_user_id ORDER BY CASE role WHEN 'admin' THEN 1 WHEN 'coach' THEN 2 ELSE 3 END LIMIT 1 $$;
CREATE POLICY "Users read own roles" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.get_user_role(auth.uid())='admin');
ALTER TABLE public.profiles ADD COLUMN approval_status text NOT NULL DEFAULT 'pending';
UPDATE public.profiles SET approval_status=CASE WHEN is_active THEN 'approved' ELSE 'pending' END;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_approval_status_valid CHECK(approval_status IN ('pending','approved','rejected'));
CREATE OR REPLACE FUNCTION public.has_learning_access() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND is_active AND approval_status='approved') $$;
CREATE OR REPLACE FUNCTION public.protect_profile_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND public.get_user_role(auth.uid()) IS DISTINCT FROM 'admin'::public.app_role AND (NEW.role IS DISTINCT FROM OLD.role OR NEW.is_active IS DISTINCT FROM OLD.is_active OR NEW.approval_status IS DISTINCT FROM OLD.approval_status OR NEW.email IS DISTINCT FROM OLD.email) THEN RAISE EXCEPTION 'Only administrators can change account access'; END IF; IF NEW.role IS DISTINCT FROM OLD.role THEN DELETE FROM public.user_roles WHERE user_id=NEW.id; INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,NEW.role); END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_profile_access BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_profile_access();
COMMENT ON COLUMN public.profiles.role IS 'Compatibility display field; authoritative permissions use protected public.user_roles through get_user_role.';
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,email,full_name,nickname,avatar_url,role,phone,is_active,approval_status) VALUES(NEW.id,NEW.email,COALESCE(NEW.raw_user_meta_data->>'full_name',''),COALESCE(NEW.raw_user_meta_data->>'nickname',''),COALESCE(NEW.raw_user_meta_data->>'avatar_url',''),'student',NEW.raw_user_meta_data->>'phone',false,'pending'); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'student'); INSERT INTO public.registration_notifications(recipient_email,recipient_type,subject,body,student_email,student_name) VALUES('roboticsansar@gmail.com','admin','New student registration','A new student is waiting for approval.',NEW.email,COALESCE(NEW.raw_user_meta_data->>'full_name','')); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.decide_student_registration(_student_id uuid,_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE student public.profiles; BEGIN IF public.get_user_role(auth.uid()) IS DISTINCT FROM 'admin'::public.app_role THEN RAISE EXCEPTION 'Administrators only'; END IF; SELECT * INTO student FROM public.profiles WHERE id=_student_id AND role='student' AND approval_status='pending' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No pending student found'; END IF; UPDATE public.profiles SET is_active=_approve, approval_status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END WHERE id=_student_id; IF _approve THEN INSERT INTO public.registration_notifications(recipient_email,recipient_type,subject,body,student_email,student_name) VALUES(student.email,'student','Your registration is approved','Your Ansar Learning Center account is approved. You can now sign in and access your lessons.',student.email,student.full_name); END IF; END $$;
REVOKE ALL ON FUNCTION public.decide_student_registration(uuid,boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.decide_student_registration(uuid,boolean) TO authenticated;
CREATE POLICY "Students read own approval notifications" ON public.registration_notifications FOR SELECT TO authenticated USING(recipient_type='student' AND student_email=(SELECT email FROM public.profiles WHERE id=auth.uid()));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['announcements','assignments','assignment_responses','books','book_categories','book_chapters','categories','chapter_questions','questions','student_chapter_answers','student_submissions','writer_essays','talk_sections','student_section_assignments','classroom_members','classrooms','learning_links','chat_messages','chat_rooms'] LOOP EXECUTE format('CREATE POLICY "Approved accounts only" ON public.%I AS RESTRICTIVE FOR ALL TO public USING(public.has_learning_access()) WITH CHECK(public.has_learning_access())',t); END LOOP; END $$;